// @agent-office-dsh-roles-plugin — generated by `agent-office roles install --agent dsh`.
// Edits are preserved unless install/remove is given --force.
// The composition mirrors DSH's Standard preset. Only the persona and the
// independent-subagent allowlist change; no services are imported by name.
const ROLES = __ROLES__

export const name = "agent-office-roles"
// Presets are a Web/Desktop capability. A globally mounted roles row must not
// put preset-free profiles such as headless into a permanent pending state.
export const inject = []

function platformExpression(row) {
  const expression = row?.disabled?.__agentOfficeJs
  if (expression === "process.platform === 'win32'") return process.platform === "win32"
  if (expression === "process.platform !== 'win32'") return process.platform !== "win32"
  return row?.disabled
}

function materialize(rows) {
  return rows.map((original) => {
    const row = structuredClone(original)
    if ("disabled" in row) row.disabled = platformExpression(row)
    if (Array.isArray(row.config)) row.config = materialize(row.config)
    return row
  })
}

function pluginsFor(role) {
  return materialize(role.plugins)
}

export function apply(ctx) {
  ctx.inject(["agentPresets"], (ctx) => {
    ctx.effect(async () => {
      const disposers = []
      try {
        // Registration is serial: a definition's tools may inspect the other role
        // ids while it mounts. Existing agents keep the revision they already use.
        for (const role of ROLES) {
          disposers.push(await ctx.agentPresets.register({
            id: role.id,
            name: role.name,
            description: role.description,
            order: role.order,
            plugins: pluginsFor(role),
          }))
        }
      } catch (error) {
        for (const dispose of disposers.reverse()) await dispose()
        throw error
      }
      return async () => {
        for (const dispose of disposers.reverse()) await dispose()
      }
    }, "agent-office-roles.register")
  })
}
